16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.time.Period;
26	import java.time.temporal.ChronoUnit;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "title")
41	    private String title;
42	
43	    @Column(name = "address")
44	    @NotEmpty
45	    private String address;
46	
47	    @Column(name = "address_line1")
48	    private String addressLine1;
49	
50	    @Column(name = "address_line2")
51	    private String addressLine2;
52	
53	    @Column(name = "city")
54	    @NotEmpty
55	    private String city;
56	
57	    @Column(name = "telephone")
58	    @NotEmpty
59	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
60	    private String telephone;
61	
62	    @Column(name = "email")
63	    private String email;
64	
65	    @Column(name = "postcode")
66	    private String postcode;
67	
68	    @Column(name = "registration_date")
69	    private LocalDate registrationDate;
70	
71	    @Column(name = "birth_date")
72	    private LocalDate birthDate;
73	
74	    @Column(name = "customer_code")
75	    private String customerCode;
76	
77	    @Column(name = "household_id")
78	    private String householdId;
79	
80	    @Column(name = "namesake_count")
81	    private Integer namesakeCount;
82	
83	    @Column(name = "household_size")
84	    private Integer householdSize;
85	
86	    @Column(name = "possible_duplicate")
87	    private Boolean possibleDuplicate;
88	
89	    @Column(name = "possible_duplicate_of")
90	    private Integer possibleDuplicateOf;
91	
92	    @Column(name = "deleted", nullable = false)
93	    private boolean deleted = false;
94	
95	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
96	    private Set<Pet> pets;
97	
98	    public String getTitle() {
99	        return this.title;
100	    }
101	
102	    public void setTitle(String title) {
103	        this.title = title;
104	    }
105	
106	    /**
107	     * The owner's salutation: the {@link #getTitle() title} followed by a space and the last name
108	     * (e.g. {@code "DR Franklin"}) when a title is present, or just the last name when no title has
109	     * been supplied.
110	     */
111	    public String getSalutation() {
112	        if (this.title == null || this.title.isEmpty()) {
113	            return this.getLastName();
114	        }
115	        return this.title + " " + this.getLastName();
116	    }
117	
118	    public String getAddress() {
119	        return this.address;
120	    }
121	
122	    public void setAddress(String address) {
123	        this.address = address;
124	    }
125	
126	    public String getAddressLine1() {
127	        return this.addressLine1;
128	    }
129	
130	    public void setAddressLine1(String addressLine1) {
131	        this.addressLine1 = addressLine1;
132	    }
133	
134	    public String getAddressLine2() {
135	        return this.addressLine2;
136	    }
137	
138	    public void setAddressLine2(String addressLine2) {
139	        this.addressLine2 = addressLine2;
140	    }
141	
142	    public String getCity() {
143	        return this.city;
144	    }
145	
146	    public void setCity(String city) {
147	        this.city = city;
148	    }
149	
150	    public String getTelephone() {
151	        return this.telephone;
152	    }
153	
154	    public void setTelephone(String telephone) {
155	        this.telephone = telephone;
156	    }
157	
158	    /**
159	     * The owner's stored E.164 {@link #getTelephone() telephone} formatted for humans: the country
160	     * code, a space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}).
161	     * The raw {@link #getTelephone() telephone} stays in E.164 form. Absent until a telephone has
162	     * been set.
163	     */
164	    public String getTelephoneDisplay() {
165	        return Telephone.forDisplay(this.telephone);
166	    }
167	
168	    public String getEmail() {
169	        return this.email;
170	    }
171	
172	    public void setEmail(String email) {
173	        this.email = email;
174	    }
175	
176	    public String getPostcode() {
177	        return this.postcode;
178	    }
179	
180	    public void setPostcode(String postcode) {
181	        this.postcode = postcode;
182	    }
183	
184	    public LocalDate getRegistrationDate() {
185	        return this.registrationDate;
186	    }
187	
188	    public void setRegistrationDate(LocalDate registrationDate) {
189	        this.registrationDate = registrationDate;
190	    }
191	
192	    public LocalDate getBirthDate() {
193	        return this.birthDate;
194	    }
195	
196	    public void setBirthDate(LocalDate birthDate) {
197	        this.birthDate = birthDate;
198	    }
199	
200	    public String getCustomerCode() {
201	        return this.customerCode;
202	    }
203	
204	    public void setCustomerCode(String customerCode) {
205	        this.customerCode = customerCode;
206	    }
207	
208	    public String getHouseholdId() {
209	        return this.householdId;
210	    }
211	
212	    public void setHouseholdId(String householdId) {
213	        this.householdId = householdId;
214	    }
215	
216	    public Integer getNamesakeCount() {
217	        return this.namesakeCount;
218	    }
219	
220	    public void setNamesakeCount(Integer namesakeCount) {
221	        this.namesakeCount = namesakeCount;
222	    }
223	
224	    public Integer getHouseholdSize() {
225	        return this.householdSize;
226	    }
227	
228	    public void setHouseholdSize(Integer householdSize) {
229	        this.householdSize = householdSize;
230	    }
231	
232	    /**
233	     * Whether this owner, though not a hard duplicate, shares an existing owner's last name and
234	     * postcode while holding a different telephone. Resolved at creation and stored so it is
235	     * reported consistently on every later read.
236	     */
237	    public Boolean getPossibleDuplicate() {
238	        return this.possibleDuplicate;
239	    }
240	
241	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
242	        this.possibleDuplicate = possibleDuplicate;
243	    }
244	
245	    /**
246	     * The id of the existing owner this owner is a possible duplicate of, or {@code null} when it
247	     * is not a possible duplicate.
248	     */
249	    public Integer getPossibleDuplicateOf() {
250	        return this.possibleDuplicateOf;
251	    }
252	
253	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
254	        this.possibleDuplicateOf = possibleDuplicateOf;
255	    }
256	
257	    /**
258	     * Whether this owner has been soft-deleted. A soft-deleted owner keeps its row and remains
259	     * retrievable, but is ignored by the create endpoint's duplicate and identity checks. A newly
260	     * created owner is never deleted.
261	     */
262	    public boolean isDeleted() {
263	        return this.deleted;
264	    }
265	
266	    public void setDeleted(boolean deleted) {
267	        this.deleted = deleted;
268	    }
269	
270	    /**
271	     * The owner's identity key: the single derived value used to detect duplicate owners, formed
272	     * as {@code normalizedTelephone + '|' + email + '|' + householdId} where an absent telephone,
273	     * email or household contributes an empty string. Two owners are duplicates only when their
274	     * whole identity keys are equal, so housemates that share a {@code householdId} but hold
275	     * different telephones have distinct identity keys and are both allowed.
276	     */
277	    public String getIdentityKey() {
278	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
279	    }
280	
281	    private static String orEmpty(String value) {
282	        return value == null ? "" : value;
283	    }
284	
285	    /**
286	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
287	     * last two digits of the registration date's year (e.g. {@code 'SMI-0007-M26'}). Derived
288	     * from the owner's own fields; absent until both the customer code and registration date
289	     * have been assigned.
290	     */
291	    public String getMembershipNumber() {
292	        if (this.customerCode == null || this.registrationDate == null) {
293	            return null;
294	        }
295	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
296	    }
297	
298	    /**
299	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of the
300	     * {@link #getCustomerCode() customer code}. Absent until the customer code has been assigned.
301	     */
302	    public Integer getCheckDigit() {
303	        if (this.customerCode == null) {
304	            return null;
305	        }
306	        return Luhn.checkDigit(this.customerCode);
307	    }
308	
309	    /**
310	     * The owner's tenure in whole days: the number of days elapsed from the
311	     * {@link #getRegistrationDate() registration date} up to today. A freshly registered owner has
312	     * a tenure of zero. Absent until a registration date is present.
313	     */
314	    public Long getTenureDays() {
315	        if (this.registrationDate == null) {
316	            return null;
317	        }
318	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
319	    }
320	
321	    /**
322	     * The owner's membership points, a score derived from the owner's own fields: starting from 0,
323	     * the owner earns 2 points when an email address is present, 1 point when this owner has no
324	     * namesakes ({@code namesakeCount} is 0), 2 points for a household of 3 or more members, and 3
325	     * points once the owner's {@link #getTenureDays() tenure} exceeds 365 days.
326	     */
327	    public Integer getMembershipPoints() {
328	        int points = 0;
329	        boolean hasEmail = this.email != null && !this.email.isEmpty();
330	        if (hasEmail) {
331	            points += 2;
332	        }
333	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
334	        if (unique) {
335	            points += 1;
336	        }
337	        boolean sharedHousehold = this.householdSize != null && this.householdSize >= 3;
338	        if (sharedHousehold) {
339	            points += 2;
340	        }
341	        Long tenureDays = getTenureDays();
342	        boolean tenured = tenureDays != null && tenureDays > 365;
343	        if (tenured) {
344	            points += 3;
345	        }
346	        return points;
347	    }
348	
349	    /**
350	     * The owner's membership level, a number from 1 to 4 derived from the owner's
351	     * {@link #getMembershipPoints() membership points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and
352	     * 4 for 6 or more.
353	     */
354	    public Integer getMembershipLevel() {
355	        int points = getMembershipPoints();
356	        if (points >= 6) {
357	            return 4;
358	        }
359	        if (points >= 4) {
360	            return 3;
361	        }
362	        if (points >= 2) {
363	            return 2;
364	        }
365	        return 1;
366	    }
367	
368	    /**
369	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customer code} (the
370	     * region derived from the postcode when the identity was assigned), or {@link Regions#UNKNOWN}
371	     * before a customer code has been assigned.
372	     */
373	    public String getLocality() {
374	        if (this.customerCode == null) {
375	            return Regions.UNKNOWN;
376	        }
377	        int separator = this.customerCode.indexOf('-');
378	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
379	    }
380	
381	    /**
382	     * The owner's timezone: the IANA timezone name for the owner's {@link #getLocality() locality}
383	     * from the fixed region-to-timezone table (NSW&rarr;Australia/Sydney, VIC&rarr;Australia/Melbourne,
384	     * QLD&rarr;Australia/Brisbane), or absent when the locality has no known timezone.
385	     */
386	    public String getTimezone() {
387	        return Regions.timezoneOf(getLocality());
388	    }
389	
390	    /**
391	     * The owner's preferred contact channel, derived from the owner's own fields:
392	     * {@code "EMAIL"} when an {@link #getEmail() email} is present, otherwise {@code "PHONE"}.
393	     */
394	    public String getContactPreference() {
395	        boolean hasEmail = this.email != null && !this.email.isEmpty();
396	        return hasEmail ? "EMAIL" : "PHONE";
397	    }
398	
399	    /**
400	     * The owner's age band, derived from the owner's own fields: the whole years between
401	     * {@link #getBirthDate() birth date} and {@link #getRegistrationDate() registration date}
402	     * classified as {@code "MINOR"} (under 18), {@code "ADULT"} (18-64) or {@code "SENIOR"}
403	     * (65 or older). Absent until a birth date and a registration date are both present.
404	     */
405	    public String getAgeBand() {
406	        if (this.birthDate == null || this.registrationDate == null) {
407	            return null;
408	        }
409	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
410	        if (age < 18) {
411	            return "MINOR";
412	        }
413	        return age < 65 ? "ADULT" : "SENIOR";
414	    }
415	
416	    /**
417	     * Resolve the effective registration date before persisting: default it to the server's
418	     * current date when none was supplied, then roll it forward off weekends so a newly
419	     * registered owner always has a business-day registration date. Every value derived from it
420	     * (such as the {@link #getMembershipNumber() membership number}) therefore uses the adjusted
421	     * date.
422	     */
423	    @PrePersist
424	    private void resolveRegistrationDate() {
425	        if (this.registrationDate == null) {
426	            this.registrationDate = LocalDate.now();
427	        }
428	        this.registrationDate = BusinessDay.onOrAfter(this.registrationDate);
429	    }
430	
431	    protected Set<Pet> getPetsInternal() {
432	        if (this.pets == null) {
433	            this.pets = new HashSet<>();
434	        }
435	        return this.pets;
436	    }
437	
438	    protected void setPetsInternal(Set<Pet> pets) {
439	        this.pets = pets;
440	    }
441	
442	    public List<Pet> getPets() {
443	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
444	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
445	        return Collections.unmodifiableList(sortedPets);
446	    }
447	
448	    public void setPets(List<Pet> pets) {
449	        this.pets = new HashSet<>(pets);
450	    }
451	
452	    public void addPet(Pet pet) {
453	        getPetsInternal().add(pet);
454	        pet.setOwner(this);
455	    }
456	
457	    /**
458	     * Return the Pet with the given name, or null if none found for this Owner.
459	     *
460	     * @param name to test
461	     * @return true if pet name is already in use
462	     */
463	    public Pet getPet(String name) {
464	        return getPet(name, false);
465	    }
466	
467	    /**
468	     * Return the Pet with the given name, or null if none found for this Owner.
469	     *
470	     * @param name to test
471	     * @return true if pet name is already in use
472	     */
473	    public Pet getPet(String name, boolean ignoreNew) {
474	        name = name.toLowerCase();
475	        for (Pet pet : getPetsInternal()) {
476	            if (!ignoreNew || !pet.isNew()) {
477	                String compName = pet.getName();
478	                compName = compName.toLowerCase();
479	                if (compName.equals(name)) {
480	                    return pet;
481	                }
482	            }
483	        }
484	        return null;
485	    }
486	
487	    public Pet getPet(Integer petId) {
488	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
489	    }
490	
491	    @Override
492	    public String toString() {
493	        return new ToStringCreator(this)
494	
495	            .append("id", this.getId())
496	            .append("new", this.isNew())
497	            .append("lastName", this.getLastName())
498	            .append("firstName", this.getFirstName())
499	            .append("address", this.address)
500	            .append("city", this.city)
501	            .append("telephone", this.telephone)
502	            .append("email", this.email)
503	            .toString();
504	    }
505	}
